def clean(df):
    df = df.copy()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', ''), errors='coerce')
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    df = df.dropna(subset=['sex'])
    return df[['penguin_id', 'sex', 'body_mass_g']]

def answer(df):
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
